import{_ as a,c as e,o as r,a1 as o}from"./chunks/framework.6sy4tsQT.js";const _=JSON.parse('{"title":"AI Agents 开发","description":null,"frontmatter":{"title":"AI Agents 开发","description":null,"date":"2026-01-27T00:00:00.000Z","tags":["Agents"]},"headers":[],"relativePath":"ai/agent-01.md","filePath":"ai/agent-01.md"}'),l={name:"ai/agent-01.md"};function n(i,t,s,g,p,d){return r(),e("div",null,[...t[0]||(t[0]=[o('<h2 id="agent-概念" tabindex="-1">Agent 概念 <a class="header-anchor" href="#agent-概念" aria-label="Permalink to &quot;Agent 概念&quot;">​</a></h2><ul><li>Agent - 智能体，自主完成用户的请求</li><li>Agent = system_prompt（角色） + tools（工具调用） + rag（知识库）</li><li>LLM prompt = system prompt + tool prompt + rag prompt</li></ul><h2 id="tavily-mcp" tabindex="-1">Tavily MCP <a class="header-anchor" href="#tavily-mcp" aria-label="Permalink to &quot;Tavily MCP&quot;">​</a></h2><p>Tavily MCP 是一个基于 <strong>Model Context Protocol</strong>（MCP）标准的轻量级服务器，旨在为大语言模型（LLM）或AI助手提供<strong>实时网络搜索、智能爬取和结构化数据提取</strong>的能力。</p><p>其核心功能包括：</p><ul><li><strong>为LLM优化的搜索</strong>：Tavily 本身是一家专注于AI搜索的公司，其搜索结果经过专门优化，更适合大模型理解和使用。</li><li><strong>遵循开放标准</strong>：通过 MCP 协议，Tavily MCP 能够与支持该协议的AI客户端（如 Cline、Cursor、Windsurf 等）无缝集成，使AI具备联网获取最新信息的能力。</li><li><strong>开源与可部署</strong>：Tavily MCP Server 是一个开源项目，开发者可以自行部署，作为AI系统与互联网之间的桥梁，实现安全、高效的实时数据交互。</li><li><strong>工具化能力</strong>：除了基本搜索，它还支持结构化数据提取，让AI不仅能“查到”，还能“理解并整理”网页内容。</li></ul><p>简而言之，<strong>Tavily MCP 让AI助手拥有了“上网查资料”的能力，并且查得准、用得好</strong>，特别适用于需要实时、准确外部信息的AI应用场景。</p><h2 id="other" tabindex="-1">other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;other&quot;">​</a></h2>',8)])])}const h=a(l,[["render",n]]);export{_ as __pageData,h as default};
